// The same 30 letters of the COX3 gene (letters 361–390 in each bird's RefSeq record; no gaps).
// Differences: peregrine–kestrel 2, sparrowhawk–eagle 6, each falcon with the sparrowhawk or the eagle 7 to 9.
const RAPTOR = {
  peregrine: 'ATCAAACCCATAAACCCCATAGAAGTACCC',
  kestrel: 'ATCAAACCCATAAATCCCATAGAAGTGCCC',
  sparrowhawk: 'ATTAGTCCACTTAACCCCCTAGAAGTACCC',
  eagle: 'ATTAACCCCCTTAATCCCCTAGAAGTCCCA',
};
// Open Tree of Life opentree16.1, induced subtree, unary nodes collapsed (otol-trees.json "raptors").
